style.css:
@-moz-document domain("fandom.com") {
/* entirely recoded everything in v1.1.0 */

/* adblock */

.bottom-ads-container, .top-ads-container, [itemprop="video"], .gpt-ad, #top_boxad, .feed-section__ad {
  display: none;
  width: 0;
  height: 0;
}

/* hide unimportant stuff */

/* variables */
:root {
  --desktop-global-navigation-width: 66px !important;
  --entity-content-link-color: rgb(175 20 98); /* i forgot if this does anything lol */
}
/* fully hidden stuff */
.global-explore-navigation__explore /* was too lazy to fix s i just removed it lol */, #age-gate, #WikiaBar, .global-footer__content, .global-footer__bottom>div:nth-child(1) , .navigation-tab--left{
  display: none ;
}
/* half opacity stuff */
.NewPage_noThumbnail__DBx3z, .global-action__link.wds-button.sign-in__anchor, .global-top-navigation__start-new-wiki, .global-footer, .global-footer__bottom>div:nth-child(2), .global-navigation__fanhub-wrapper {
  opacity: .5;
}
/* extra footer stuff because its extra special */
.global-footer__bottom, .global-footer  {
  border-top-left-radius: 999px;
  border-top-right-radius: 999px;
}

/* enhancment stuff */

/* dark mode wherever dark mode isn't at yet */
.Onboarding_content__F_8L2, .FeedContainer_moreButton__grZco, .UpdatedPages_wrapper__Wbj48, .Widget_widget__F2fBj, .RecentImages_wrapper__Lf3Eq, .NewPage_readMore__k1wXy, .PopularPage_readMore__o5Ypf, .PopularPages_wrapper__2QVLx, .Share_shareWrapper__Rwm_M, .FeedCard_card__habOF, .NewPage_wrapper__PmZVg, #WikiModule_576_4396_1 {
  background-color: var(--fandom-global-nav-background-color);
}
.entity-content.is-large-content:before {
    background: linear-gradient(to bottom, rgba(var(--entity-content-background-color--rgb), 0) 300px, var(--fandom-global-nav-background-color) 100%);
}
/* gradient stuff (still dark mode) */
.NewPage_articleTitleWrapper__SYtTx {
    background-image: linear-gradient(0deg, var(--fandom-global-nav-background-color)  0, transparent);
}
.Carousel_carouselContainer__By02s.Carousel_shadowRight__bY39l:after {
    background-image: linear-gradient(270deg, var(--fandom-global-nav-background-color) 45%, hsla(0, 0%, 100%, 0));
}
.Carousel_carouselContainer__By02s.Carousel_shadowLeft__LJ97f:before {
    background-image: linear-gradient(90deg, var(--fandom-global-nav-background-color) 45%, hsla(0, 0%, 100%, 0));
}
/* small read more button fix on some cards in fan central */
.ExpandButton_expandButton__BDLbL, .ReadMoreButton_readMore__foWdI {
  --wds-primary-button-background-color: #fff;
  --wds-primary-button-background-color--hover: #fff;
  --wds-primary-button-label-color: #520044;
  background-color: rgba(255,255,255,.5) !important;
  border: none;
  color: var(--wds-primary-button-label-color) !important;
}
.ReadMoreButton_readMore__foWdI {
  bottom: 12px;
  box-shadow: 0 0 6px 0 rgba(30, 12, 27, .3);
  left: 50%;
  position: absolute;
  transform: translateX(-50%);
  border-radius: 3px; 
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .15px;
  line-height: 16px;
  margin: 0;
  min-height: 18px;
  padding: 7px 18px;
  text-transform: uppercase;
  transition-duration: .3s;
  transition-property: background-color, border-color, color;
  /* ima be honest i just pasted the normal button css here and changed some stuff lol */
}
.ExpandButton_expandButton__BDLbL:hover, .ReadMoreButton_readMore__foWdI:hover {
  background-color: white !important;
  border: 1px solid white;
  color: var(--wds-primary-button-label-color);
  text-decoration: none;
}
/* popular page btn */
.PopularPage_readMore__o5Ypf, .NewPage_readMore__k1wXy {
  border-color: var(--fandom-global-nav-background-color);
  box-shadow: -10px 0 5px var(--fandom-global-nav-background-color);
}
/* button svg color */
.wds-button>svg {
  fill: var(--fandom-text-color--secondary);
}
.wds-button>svg.wds-icon.wds-icon-small, .sign-in__icon {
  fill: currentcolor !important;
}
.wds-button.wds-is-text.page-header__action-button {
	color: var(--wds-text-button-label-color);
}
.fandom-community-header a {
    color: var(--theme-community-header-color) !important;
}
.fandom-sticky-header a {
    color: var(--theme-sticky-nav-text-color) !important;
}

.wiki-tools .wds-button.wds-is-secondary:hover {
    color: #9b004e !important;
}
/* view more btn */
.FeedContainer_moreButton__grZco {
  border: none;
}
/* text color fix*/
.Onboarding_description__8HekL>ol>li, .Onboarding_description__8HekL>ol>li::before, .Onboarding_description__8HekL, .Onboarding_header__DV5_I, .FeedContainer_moreButton__grZco, .FeedEmptyState_helperText__wqe6m, .FeedEmptyState_heading__Iz9KB, .WelcomeWidget_noAccount__qb2Tb, .WelcomeWidget_description__XM9xm, .MyFandomsZeroState_zeroState__TDysK, .FandomListItem_fandomFollowers__mQSkC, .CarouselCards_detailsInfo__Nb3yG, .CarouselCards_detailsArticle__Xe8uX, .Footer_comments__GpmWW, .Footer_upvotes__mPVdt, .post__og-source, .post__og-title, .Title_titleText__OWJ3w, .Title_title__d37az, .entity-content, .Header_metadata__mYCij, .NewPage_textContent__43VPw, .PopularPage_pageDescription___SxL_, .PopularPage_pageTitle__ouV8H {
	color: var(--fandom-text-color--secondary) !important;
}
.wds-icon, .wds-icon.wds-icon-small {
  fill: var(--fandom-text-color--secondary);
}
.wds-button.wds-is-text, .WelcomeWidget_title__BoyTn, .CarouselCards_detailsTitle__8dSaV, .Widget_title__ZmHqQ, .wds-button, .wds-button.wds-is-secondary {
  color: #9b004e;
}
.wds-button {
  color: var(--wds-primary-button-label-color);
}
.Tags_tagsContainer__2aBF9 a {
    color: #9b004e;
}
/* out of ideas :despair: */
}

@-moz-document domain("www.fandom.com") {
/* show some of the hidden features that should be brought back on fandom's main page */
.global-footer__content {
  display: flex;
}
.global-footer, .global-footer__bottom>div:nth-child(2), .global-action__link.wds-button.sign-in__anchor, .global-top-navigation__start-new-wiki {
  opacity: 1;
}
.global-footer__bottom, .global-footer  {
  border-radius: 0;
}
}
